 * chat, or email) is still a legitimate top-level document navigation. Only
 * sub-resource and API traffic has to stay same-origin; safe navigations are
 * allowed through because the mutation guards below still require the JSON
 * content type and the local session token.
 */
function isTopLevelDocumentNavigation(context: Context): boolean {
  if (context.req.method !== "GET" && context.req.method !== "HEAD") return false;
  const mode = context.req.header("sec-fetch-mode");
  if (mode && mode !== "navigate") return false;
  const destination = context.req.header("sec-fetch-dest");
  return !destination || destination === "document";
}

